const engine=require('watch-engine');const pico=require('picomatch');const path=require('node:path');
function watch(input,options={}){const cwd=path.resolve(options.cwd||process.cwd());const patterns=[input].flat().map(p=>path.isAbsolute(p)?path.relative(cwd,p).replaceAll('\\','/'):p.replaceAll('\\','/'));const scans=patterns.map(p=>pico.scan(p));const roots=scans.map(s=>s.isGlob?(s.base||'.'):s.input);const accept=p=>patterns.some((pattern,i)=>scans[i].isGlob?pico(pattern,{dot:true})(p):p===pattern||p.startsWith(pattern.replace(/\/$/,'')+'/'));const original=options.ignored;const ignored=(file,stats)=>{const rel=path.isAbsolute(file)?path.relative(cwd,file).replaceAll('\\','/'):file.replaceAll('\\','/');if(typeof original==='function'&&original(file,stats))return true;if(original instanceof RegExp&&original.test(file))return true;if(typeof original==='string'&&pico(original,{dot:true})(rel))return true;if(Array.isArray(original)&&original.some(p=>typeof p==='string'?pico(p,{dot:true})(rel):p instanceof RegExp&&p.test(file)))return true;return Boolean(stats?.isFile()&&!accept(rel));};return engine.watch([...new Set(roots)],{...options,cwd,ignored});}
module.exports={...engine,watch};
